function witnessFor(sectionKey: string): CorpusPassage["witnesses"] {
  return [{ manuscriptKey: sectionKey.startsWith("rvi-") ? "kv9" : "seti-sarcophagus" }];
}

function buildPassages(): CorpusPassage[] {
  const passages: CorpusPassage[] = [];
  GATES_DIVISIONS.forEach((division, i) => {
    const meta = DIVISIONS[division.hour];
    const divisionKey = `${PREFIX}.${division.hour}`;
    passages.push({
      key: divisionKey,
      divisionKind: "hour",
      label: meta.label,
      reference: `Budge's division ${division.hour}; The Egyptian Heaven and Hell, vol. II, chap. ${division.chapter}`,
      sourceKey: "budge-heaven-hell",
      summary: meta.summary,
      notes: [`Budge's heading: '${division.heading}'`, meta.notes].filter(Boolean).join(" "),
      verificationStatus: "unverified",
      layers: cited(division.hour),
      witnesses: [{ manuscriptKey: "seti-sarcophagus", locus: `Division ${division.hour} (Budge)` }],
      dates: i === 0 ? DATES : undefined,
      themes: meta.themes?.map(([themeKey, note]) => ({ themeKey, note })),
      images: imagesFor(BOOK_OF_GATES_IMAGES, divisionKey),
    });
    for (const section of division.sections) {
      const key = `${divisionKey}.${section.key}`;
      const where = `vol. II, chap. ${division.chapter}, ${section.pages}`;
      passages.push({
        key,
        parentKey: divisionKey,
        divisionKind: sectionDivisionKind(section.key),
        label: `Division ${division.hour}: ${section.label.charAt(0).toLowerCase()}${section.label.slice(1)}`,
        reference: `Budge, The Egyptian Heaven and Hell, ${where}`,
        sourceKey: "budge-heaven-hell",
        notes:
          division.hour <= 5 && (section.key === "upper" || section.key === "lower")
            ? `Budge describes these as the scenes on the ${section.key === "upper" ? "right" : "left"} of the boat's path; from the seventh division on he calls the two sides the upper and lower registers. Filing them as the ${section.key} register is this import's choice.`
            : undefined,
        verificationStatus: "unverified",
        layers: [budgeLayer(section, where)],
        witnesses: witnessFor(section.key),
        images: imagesFor(BOOK_OF_GATES_IMAGES, key),
      });
    }
  });
  return passages;
}

